import { test, expect } from '@playwright/test';

test.describe('Dropdown Selection Test', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/dropdown');
  });

  test('should display disabled prompt and allow selection of option 2', async ({ page }) => {
    // Verify initial disabled prompt is visible
    const prompt = page.getByRole('status');
    await expect(prompt).toContainText('Please select an option');

    // Verify dropdown is disabled initially
    const dropdown = page.getByRole('combobox');
    await expect(dropdown).toBeDisabled();

    // Verify dropdown has no selected option initially
    const options = page.locator('[data-testid="dropdown-options"]');
    await expect(options).toHaveCount(3);

    // Verify option 2 is visible
    const option2 = page.getByText('Option 2');
    await expect(option2).toBeVisible();

    // Verify option 2 is not selected
    const selectedValue = page.getByRole('option', { name: /option 2/i });
    await expect(selectedValue).not.toBeSelected();

    // Click on option 2 to select it
    await option2.click();

    // Verify dropdown is now enabled
    await expect(dropdown).not.toBeDisabled();

    // Verify option 2 is now selected
    await expect(selectedValue).toBeSelected();

    // Verify dropdown value is set to '2'
    const value = page.getByRole('heading', { name: /value: 2/i });
    await expect(value).toBeVisible();

    // Verify prompt is no longer visible
    await expect(prompt).not.toBeVisible();
  });

  test('should handle selection of multiple options and apply them', async ({ page }) => {
    // Verify initial disabled prompt is visible
    const prompt = page.getByRole('status');
    await expect(prompt).toContainText('Please select an option');

    // Verify dropdown is disabled initially
    const dropdown = page.getByRole('combobox');
    await expect(dropdown).toBeDisabled();

    // Verify dropdown has no selected option initially
    const options = page.locator('[data-testid="dropdown-options"]');
    await expect(options).toHaveCount(3);

    // Verify option 1 is visible
    const option1 = page.getByText('Option 1');
    await expect(option1).toBeVisible();

    // Verify option 2 is visible
    const option2 = page.getByText('Option 2');
    await expect(option2).toBeVisible();

    // Verify option 3 is visible
    const option3 = page.getByText('Option 3');
    await expect(option3).toBeVisible();

    // Click on option 1 to select it
    await option1.click();

    // Verify option 1 is now selected
    const selectedValue1 = page.getByRole('option', { name: /option 1/i });
    await expect(selectedValue1).toBeSelected();

    // Click on option 2 to select it
    await option2.click();

    // Verify option 2 is now selected
    const selectedValue2 = page.getByRole('option', { name: /option 2/i });
    await expect(selectedValue2).toBeSelected();

    // Verify dropdown value is set to '1,2'
    const value = page.getByRole('heading', { name: /value: 1,2/i });
    await expect(value).toBeVisible();

    // Verify prompt is no longer visible
    await expect(prompt).not.toBeVisible();

    // Verify dropdown is still enabled
    await expect(dropdown).not.toBeDisabled();

    // Verify option 3 is still visible
    await expect(option3).toBeVisible();
  });
});
